773		if err == nil || !strings.Contains(err.Error(), `recorded name "stable" does not match snapshot "releases/stable"`) {
774			t.Fatalf("err=%v", err)
775		}
776		// The healthy list must survive the rejected restore.
777		if entries, err := store.List(); err != nil || len(entries) != 1 {
778			t.Fatalf("entries=%+v err=%v", entries, err)
779		}
780		// Repair the record through the API: a healthy record named in full is
781		// published again. Restoring it succeeds even when the current index is
782		// unreadable, proving a healthy snapshot can replace a corrupt current
783		// mapping without requiring it to load.
784		if err := os.Remove(recordPath); err != nil {
785			t.Fatal(err)
786		}
787		if _, err := store.CreateSnapshot("releases/stable"); err != nil {
788			t.Fatal(err)
789		}
790		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte("{not json"), 0o644); err != nil {
