795		}
796		entries, err := store.List()
797		if err != nil {
798			t.Fatal(err)
799		}
800		if len(entries) != 1 || entries[0].Name != "a.txt" {
801			t.Fatalf("entries after healthy restore=%+v", entries)
802		}
803	}
